  const dome = []; for (let y = yb; y >= yc; y -= 2) dome.push([xl(y), y]); for (let y = yc; y <= yb; y += 2) dome.push([xr(y), y]);
  s += `<path class="zb" style="stroke:none;opacity:.6" d="${dome.map((p, i) => (i ? "L" : "M") + f1(p[0]) + "," + f1(p[1])).join(" ")} Z"/>` + path(dome, "bold");
