  const vapB = []; for (let k = 0; k <= 30; k++) { const x = xB + (458 - xB) * k / 30; vapB.push([x, yP2 + 82 * Math.pow((x - xB) / (458 - xB), 0.7)]); }
  const vapD = []; for (let k = 0; k <= 20; k++) { const x = xR1 + (458 - xR1) * k / 20; vapD.push([x, yP1 + 16 * Math.pow((x - xR1) / (458 - xR1), 0.7)]); }
  s += iso(xA2 - 4, 22, xA2, yP2, xB, vapB) + iso(xD - 3, 22, xD, yP1, xR1, vapD);
  s += `<path class="k" style="stroke:var(--muted);stroke-width:1.2;fill:none" d="M188,14 C191,40 186,${yc} ${xc},${yc} C214,${yc} 300,90 458,114"/>`;
  s += Tx(458, 110, R`T_{\text{c}}`, "sm", "end") + Tx(458, 196, R`T_B`, "sm", "end") + Tx(458, 262, R`T_D`, "sm", "end");
  /* cycle */
  const adi = []; for (let k = 0; k <= 30; k++) { const u = k / 30; adi.push([xB + (xC - xB) * u, yP2 + (yP1 - yP2) * (1 - Math.pow(1 - u, 1.7))]); }
  s += path([[xD, yP1], [xD, yP2], [xA2, yP2], [xB, yP2]], "vr", "fill:none;stroke-width:2.4") + path(adi, "vr", "fill:none;stroke-width:2.4") + path([[xC, yP1], [xD, yP1]], "vr", "fill:none;stroke-width:2.4");
  s += ar(xD, 200, xD, 176, "r") + ar(220, yP2, 236, yP2, "r") + ar(adi[14][0], adi[14][1], adi[16][0], adi[16][1], "r") + ar(250, yP1, 234, yP1, "r");
  s += dash(40, yP2, xD, yP2) + dash(40, yP1, xD, yP1) + Tx(34, yP2 + 4, R`P_2`, "sm", "end") + Tx(34, yP1 + 4, R`P_1`, "sm", "end");
  s += dot(xD, yP2, "ptr") + T(xD - 6, yP2 - 7, "A", "it r", "end") + dot(xA2, yP2, "ptr") + T(xA2 + 2, yP2 - 8, "A′", "it r") + dot(xB, yP2, "ptr") + T(xB + 6, yP2 - 7, "B", "it r") + dot(xC, yP1, "ptr") + T(xC + 6, yP1 - 8, "C", "it r") + dot(xD, yP1, "ptr") + T(xD - 6, yP1 + 16, "D", "it r", "end");
  s += dot(xc, yc) + T(xc + 8, yc - 8, "point critique", "sm");
  s += T(46, 190, "liquide", "sm") + T(420, 150, "vapeur", "sm", "middle") + T(250, 214, "liquide + vapeur", "sm", "middle");
  return fig(480, 310, "Cycle de Rankine dans le diagramme de Clapeyron", s, "Allure du cycle dans le diagramme de Clapeyron $(P,v)$ (échelles non respectées : $v_v$ est environ mille fois plus grand que $v_\\ell$). Le cycle est parcouru dans le sens horaire : c'est un moteur.");
