const F_JE = (() => {
  const X = E => 200 + E * 200, Y0 = 140, jc = E => -8.2 * (Math.exp(-E / 0.03) - 1), ja = E => 6 * (Math.exp((E - 1.3) / 0.07) - 1);
  let s = ar(20, Y0, 550, Y0, "k").replace(/class="vk"/, 'class="ax"').replace(/class="hk"/, 'class="axh"') + ar(X(0), 268, X(0), 12, "k").replace(/class="vk"/, 'class="ax"').replace(/class="hk"/, 'class="axh"') + T(546, Y0 + 18, "E (V)", "sm", "end") + T(X(0) + 6, 18, "j", "it");
  const cat = []; for (let E = -0.1; E <= 0.0001; E += 0.002) { const v = Y0 - jc(E); if (v < 262) cat.push([X(E), v]); } cat.push([X(0), Y0]); cat.push([X(1.3), Y0]);
  const ano = []; for (let E = 1.3; E <= 1.62; E += 0.002) { const v = Y0 - ja(E); if (v > 16) ano.push([X(E), v]); }
  s += path(cat, "vb", "fill:none;stroke-width:2.4") + path(ano, "vr", "fill:none;stroke-width:2.4");
  const jw = 60, Ea = 1.3 + 0.07 * Math.log(1 + jw / 6), Ec = -0.03 * Math.log(1 + jw / 8.2);
  s += dash(X(Ec), Y0 + jw, X(Ea), Y0 + jw) + dash(X(Ea), Y0 - jw, X(Ea), Y0 + jw) + ar(X(Ec) + 2, Y0 + jw + 14, X(Ea) - 2, Y0 + jw + 14, "k") + ar(X(Ea) - 2, Y0 + jw + 14, X(Ec) + 2, Y0 + jw + 14, "k") + Tx((X(Ec) + X(Ea)) / 2, Y0 + jw + 30, R`U_c(j)\ \text{(hors chute ohmique)}`, "sm", "middle");
  s += ar(X(0), Y0 - 22, X(1.3), Y0 - 22, "v") + ar(X(1.3), Y0 - 22, X(0), Y0 - 22, "v") + Tx(X(0.65), Y0 - 30, R`U_{\min}\approx1{,}3\ \mathrm V`, "sm v", "middle");
  s += ln(X(1.23), Y0 - 4, X(1.23), Y0 + 4, "ax") + Tx(X(1.23) - 4, Y0 + 18, R`1{,}23`, "sm", "end") + Tx(X(0) - 6, Y0 + 18, R`0`, "sm", "end");
  s += Tx(X(1.42), 30, R`2\mathrm{H_2O}\to\mathrm{O_2}+4\mathrm{H^+}+4e^-`, "sm r", "end") + T(X(1.42), 46, "couple lent : seuil au-delà de 1,23 V", "sm r", "end") + Tx(24, 40, R`2\mathrm{H^+}+2e^-\to\mathrm{H_2}`, "sm b") + T(24, 56, "couple rapide :", "sm b") + T(24, 70, "courant dès 0 V", "sm b");
  return fig(560, 270, "Courbes intensité-potentiel de l'électrolyse de l'eau", s, "Allure des courbes $j = f(E)$ : la branche cathodique (bleu, couple $\\mathrm{H^+/H_2}$ rapide) démarre à $E = 0$, la branche anodique (rouge, couple $\\mathrm{O_2/H_2O}$ lent) seulement vers $1{,}3\\ \\mathrm V$. Pour une densité de courant $j$, la tension est l'écart horizontal entre les deux branches.");
})();

